<?php

# @autogenerated
declare(strict_types=1);
namespace Civi\Lughauth\Features\Document\TemplateAsset\Domain\ValueObject\Holder;

use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use Civi\Lughauth\Features\Document\TemplateAsset\Domain\ValueObject\TemplateAssetContentVO;

trait TemplateAssetContentAttributeHolder
{
  protected TemplateAssetContentVO|string|null $content = null;
  protected bool $contentAssigned = false;

  public function getContentOrDefault(TemplateAssetContentVO $content): TemplateAssetContentVO
  {
  if( $this->contentAssigned ) {
    \assert( null !== $this->content );
    return TemplateAssetContentVO::from($this->content);
  } else {
    return $content;
  }
  }
  public function content(TemplateAssetContentVO|string $content): static
  {
    $this->content = $content;
    $this->contentAssigned = true;
    return $this;
  }
  public function getContent(): ?string
  {
    return $this->content instanceof TemplateAssetContentVO ? $this->content->value() : $this->content;
  }
  public function isContentAssigned(): bool
  {
    return $this->contentAssigned;
  }
  public function writeContentTo(mixed $att): void
  {
    if ($this->contentAssigned) {
      \assert(null !== $this->content);
      $att->content($this->content);
    }  }
  public function readContentFrom(mixed $att): void
  {
    if ($att->isContentAssigned() ) {
      $content = $att->getContent();
      \assert(null !== $content);
      $this->content($content);
    }
  }
  public function unsetContent(): static
  {
    $this->contentAssigned = false;
    return $this;
  }
  protected function withDefaultContent(): void   
  {
  }
  protected function withAssertedContentRules(self $value, ConstraintFailList $errorsList): void  
  {
    if ($value->contentAssigned = $this->contentAssigned) {
      $value->content = TemplateAssetContentVO::tryFrom($this->content, $errorsList);
    }
  }
}
